<script>
  document.getElementById('yr').textContent=new Date().getFullYear();

  // Ticker
  (function(){
    const items=['Importing HMS 1&2','Shredded Scrap','Used Rails R50/R65','Steel Turnings','Cast Iron Scrap','Sourcing from all countries','Bulk & container shipments','Inspected before loading'];
    const h=items.map(t=>`<span>${t}</span>`).join('');
    document.getElementById('tick').innerHTML=h+h+h+h;
  })();

  document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>document.getElementById('nav').classList.remove('open')));

  // Counters
  const co=new IntersectionObserver(es=>es.forEach(e=>{
    if(!e.isIntersecting)return;
    const el=e.target,t=+el.dataset.count,s=el.dataset.suf||'';let n=0;const st=Math.ceil(t/60);
    const iv=setInterval(()=>{n+=st;if(n>=t){n=t;clearInterval(iv)}el.textContent=n.toLocaleString()+(n===t?s:'')},25);
    co.unobserve(el);
  }),{threshold:.5});
  document.querySelectorAll('[data-count]').forEach(c=>co.observe(c));

  // Reveal
  const rv=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('show');rv.unobserve(e.target)}}),{threshold:.12});
  document.querySelectorAll('.reveal').forEach(x=>rv.observe(x));

  // Form -> WhatsApp
  document.getElementById('form').addEventListener('submit',e=>{
    e.preventDefault();
    const d=new FormData(e.target);
    const text=`New Scrap Enquiry (${d.get('role')})
Name: ${d.get('name')}
Company: ${d.get('company')}
Email: ${d.get('email')}
Phone: ${d.get('phone')}
Grade: ${d.get('grade')}
Quantity (MT): ${d.get('quantity')}
Country/Port: ${d.get('country')}
Message: ${d.get('message')}`;
    window.open('https://wa.me/91XXXXXXXXXX?text='+encodeURIComponent(text),'_blank');
    document.getElementById('msg').textContent='Opening WhatsApp to send your enquiry...';
    e.target.reset();
  });
</script>
